// Guarda el token recibido para usarlo en los próximos pedidos
const respuesta = pm.response.json();

if (respuesta.token) {
  pm.collectionVariables.set('token', respuesta.token);
  console.log('Token guardado:', respuesta.token);
}

pm.test('Devuelve un token', () => pm.expect(respuesta.token).to.be.a('string'));

if (respuesta.token) pm.collectionVariables.set('tokenCliente', respuesta.token);

const r = pm.response.json();
if (r.token) pm.collectionVariables.set('tokenAdmin', r.token);
pm.test('Devuelve un token', () => pm.expect(r.token).to.be.a('string'));

const r = pm.response.json();
if (r.token) pm.collectionVariables.set('tokenVendedor', r.token);
pm.test('Devuelve un token', () => pm.expect(r.token).to.be.a('string'));

pm.sendRequest({
  url: pm.variables.replaceIn('{{baseUrl}}/carrito'),
  method: 'GET',
  header: { Authorization: 'Bearer ' + pm.collectionVariables.get('token') },
}, (err, res) => {
  const item = res && res.json().items.find(i => i.id_accesorio === 10);
  if (item) pm.collectionVariables.set('idItemCarrito', item.id_item_carrito);
});
